outline_text:
{
  "title": "SaaS Pricing Overview",
  "theme": "default",
  "paginate": true,
  "slides": [
    {
      "title": "Agenda",
      "summary": "The three plans, per-plan limits, a feature comparison, migration discounts, and the FAQ."
    },
    {
      "title": "Plans at a Glance",
      "summary": "Starter 9 euros per user per month; Professional 19; Enterprise from 29 with a volume discount; all billed annually or monthly."
    },
    {
      "title": "Starter Plan",
      "summary": "Up to 5 users and 20 projects; community support; 10 gigabytes of storage; single sign-on not included."
    },
    {
      "title": "Professional Plan",
      "summary": "Up to 50 users, unlimited projects; priority support; 500 gigabytes; single sign-on and audit log included."
    },
    {
      "title": "Enterprise Plan",
      "summary": "Unlimited users; named support engineer; custom storage; data residency in the EU or US; onboarding workshop included."
    },
    {
      "title": "Feature Comparison: Core",
      "summary": "Rows: projects, storage, support, single sign-on. Checkmarks per plan; differences highlighted; details on the next slide."
    },
    {
      "title": "Feature Comparison: Advanced",
      "summary": "Audit log from Professional; API access everywhere; sandbox environments Enterprise only; export formats compared."
    },
    {
      "title": "Migration Discounts",
      "summary": "20 percent for the first year when moving from a competitor; 10 percent for annual prepay; both combinable until June."
    },
    {
      "title": "FAQ",
      "summary": "Can plans mix? Yes, per team. Is there a free trial? 14 days, no card. What happens at the user limit? Soft cap with a reminder."
    },
    {
      "title": "Where to Get Help",
      "summary": "The pricing calculator in the docs, sales for Enterprise, and the in-app chat for plan changes."
    }
  ]
}
